style.css:
@-moz-document domain("youtube.com") {
/* Fondo general */
    body, ytd-app, #content, #page-manager {
        background-color: #0a1a2b !important;  /* azul muy oscuro */
        color: #c0c9d8 !important;             /* texto azul grisáceo */
        font-family: "Segoe UI", sans-serif !important;
    }

    /* Barra superior */
    #masthead-container, #container, #start, #end {
        background-color: #0f2a44 !important;  /* azul apagado */
    }

    /* Menús laterales */
    ytd-guide-renderer, #guide-content {
        background-color: #13203b !important;  
        color: #c0c9d8 !important;
    }

    /* Paneles de videos y listas */
    ytd-rich-grid-renderer, ytd-rich-item-renderer, ytd-grid-video-renderer, ytd-video-renderer {
        background-color: #0f2a44 !important;
        border-radius: 6px !important;
        border: 1px solid #13203b !important;
        padding: 4px !important;
        color: #c0c9d8 !important;
    }

    /* Títulos y links */
    a, a:visited {
        color: #5a7fa0 !important;
        text-decoration: none !important;
    }

    a:hover {
        color: #7a9ec1 !important;
        text-decoration: underline !important;
    }

    /* Botones */
    ytd-toggle-button-renderer, yt-icon-button, button {
        background-color: #13203b !important;
        color: #d0d9e8 !important;
        border-radius: 6px !important;
    }

    button:hover, ytd-toggle-button-renderer:hover {
        background-color: #1a304f !important;
    }

    /* Inputs y cajas de búsqueda */
    input, textarea {
        background-color: #0f2a44 !important;
        color: #c0c9d8 !important;
        border: 1px solid #13203b !important;
        border-radius: 6px !important;
        padding: 6px !important;
    }

    /* Scrollbar personalizado */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #13203b !important;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background-color: #0a1a2b !important;
    }

    /* Menús desplegables y overlays */
    .ytp-popup, .ytd-menu-popup-renderer, #menu {
        background-color: #13203b !important;
        border: 1px solid #0f2a44 !important;
        border-radius: 6px !important;
    }
}
